// === Tab: mySketch ===
 var cellArray = [];
 var cellSize = 20; //Originally 10
 var numX, numY;

 function setup() {
   createCanvas(500, 300);
   numX = floor(width/cellSize);
   numY = floor(height/cellSize);
   //frameRate(2);
   restart();
 }

function restart() {
  for (var x = 0; x < numX; x++) {
    cellArray[x] = [];
    for (var y = 0; y < numY; y++) {
      cellArray[x][y] = new Cell(x, y);
    }
  }

  for (var x = 0; x < numX; x++) {
    for (var y = 0; y < numY; y++) {

      var above = y-1;
      var below = y+1;
      var left = x-1;
      var right = x+1;

      if (above < 0) {above = numY-1;}
      if (below == numY) {below = 0;}
      if (left < 0) {left = numX-1;}
      if (right == numX) {right = 0;}

      cellArray[x][y].addNeighbor(cellArray[left][above]);
      cellArray[x][y].addNeighbor(cellArray[left][y]);
      cellArray[x][y].addNeighbor(cellArray[left][below]);
      cellArray[x][y].addNeighbor(cellArray[x][below]);
      cellArray[x][y].addNeighbor(cellArray[right][below]);
      cellArray[x][y].addNeighbor(cellArray[right][y]);
      cellArray[x][y].addNeighbor(cellArray[right][above]);
      cellArray[x][y].addNeighbor(cellArray[x][above]);
    }
  }
	launch(5);
}

function draw() {
  background(200);

	if (keyIsPressed && keyCode == 32) { 
	} else {
		launch(averageTemp()/3);
	}

  for (var x = 0; x < numX; x++) {
    for (var y = 0; y < numY; y++) {
      cellArray[x][y].calcNexState();
    }
  }

  translate(cellSize/2, cellSize/2);

  for (var x = 0; x < numX; x++) {
    for (var y = 0; y < numY; y++) {
      cellArray[x][y].drawMe();
    }
  }
}

function mouseReleased() {
  restart();
}

function launch(num) {
	if (num < 1) {
		num = 1;
	}
	for (var i = 0; i < num; i++) {
		var cell1 = cellArray[int(random(numX))][int(random(numY))];
		cell1.nextState = 1;
		cell1.xvel = random([-1, 0, 1]);
		cell1.yvel = random([-1, 0, 1]);
	}
}

function averageTemp() {
	var totalTemp = 0;
	for (var i = 0; i < cellArray.length; i++) {
		for (var j = 0; j < cellArray[i].length; j++) {
			totalTemp += cellArray[i][j].temp;
		}
	}
	var aTemp = totalTemp/(numX*numY);
	return aTemp;
}

//<----------------------- Nuclear Fission ----------------------->
function Cell(ex, why) {
  this.neighbors = [];
  this.x = ex * cellSize;
  this.y = why * cellSize;
	this.temp = 0;
	this.nextState = 0;
	this.xvel = 0;
	this.yvel = 0;

  this.state = this.nextState;

  this.addNeighbor = function(cell) {
    append(this.neighbors, cell);
  }

  this.calcNexState = function() {
		if ((this.xvel != 0 || this.yvel != 0) && this.state == 1) {
			var targetx = this.x/cellSize + this.xvel;
			var targety = this.y/cellSize + this.yvel;
			if (targety < 0) {targety = numY-1;}
			if (targety >= numY) {targety = 0;}
			if (targetx < 0) {targetx = numX-1;}
			if (targetx >= numX) {targetx = 0;}
			target = cellArray[targetx][targety];
			if ((target.nextState == 1)||(target.state == 1)) {
				this.nextState = 0;
				target.nextState = 0;
				this.xvel = 0;
				this.yvel = 0;
				target.xvel = 0;
				target.yvel = 0;
				this.temp = 10;
				target.temp = 10;
				for (var i = 0; i < this.neighbors.length; i++) {
					this.neighbors[i].temp = 10;
				}
				for (var i = 0; i < target.neighbors.length; i++) {
					target.neighbors[i].temp = 10;
				}
			} else {
				target.nextState = this.state;
				target.xvel = this.xvel;
				target.yvel = this.yvel
				this.xvel = 0;
				this.yvel = 0;
				this.nextState = 0;
			}
		}


		var plasmaCount = this.temp;
		for (var i = 0; i < this.neighbors.length; i++) {
			plasmaCount += this.neighbors[i].temp;
		}
		if (plasmaCount > 0) {
			this.temp = (plasmaCount/9);
		}

	if ((this.x == 0 || this.x == (numX-1) * cellSize) || (this.y == 0 || this.y == (numY-1) * cellSize)) {
		if (this.temp > 0) {
			this.temp = this.temp/1.05;
		} else if (this.temp < 0) {
			this.temp = this.temp/1.05;
		}
	}
	/*
	if (this.state == 0) {
		var firingCount = 0;
		for (var i = 0; i < this.neighbors.length; i++) {
			if(this.neighbors[i].state == 1) {
				firingCount++;
			}
		}
		if (firingCount == 2) {
			this.nextState = 1;
		} else {
			this.nextState = this.state;
		}
	} else if (this.state == 1) {
		this.nextState = 2;
	} else if (this.state == 2) {
		this.nextState = 0;
	}*/
}

  this.drawMe = function() {
    this.state = this.nextState;
    stroke(0);
		switch (this.state) {
			case(1):
				fill(0);
				break;
			default:
				if (this.temp >= 0) {
					fill(255, 255-this.temp*25.5, 255-this.temp*25.5);
				} else {
					fill(10, 20, -this.temp*25.5);
				}
				break;
		}
    ellipse(this.x, this.y, cellSize, cellSize);
  }
}

